def compute(vars):
    current_maturities_2019 = vars["v1"]
    current_maturities_2018 = vars["v2"]
    average_current_maturities = (current_maturities_2019 + current_maturities_2018) / 2

    return {
        "value": average_current_maturities,
        "trace": {
            "current_maturities_2019": current_maturities_2019,
            "current_maturities_2018": current_maturities_2018,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
